def isCovered(ranges, left, right):
    diff = [0] * 52
    for a, b in ranges:
        diff[a] += 1
        diff[b + 1] -= 1
    cur = 0
    for i in range(1, 51):
        cur += diff[i]
        if left <= i <= right and cur <= 0:
            return False
    return True

